import {catalogRules} from './catalog.mjs';
import * as E from './excel-model.mjs';

export function excelUI({getState,commit,esc,notify}){
 let wb=null,filename='',sheetName='',headerRow=1,headers=[],rows=[],mapping={},choices={},step=0,skipErrors=false,result=null,root=null,busy=false;
 const xlsx=()=>{if(!window.XLSX)throw Error('Excel 组件加载失败，请刷新后重试');return window.XLSX;};
 const button=(label,action,cls='')=>`<button type="button" class="${cls}" data-excel="${action}">${label}</button>`;
 const selected=(a,b)=>a===b?' selected':'';
 function open(){wb=null;filename='';step=0;result=null;choices={};busy=false;skipErrors=false;root=document.createElement('div');root.className='excel-host';root.innerHTML='<div class="backdrop"></div><section class="excel-modal" role="dialog" aria-modal="true" aria-label="Excel 导入线索"></section>';document.querySelector('#overlay').replaceChildren(root);root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape')close();});render();}
 function close(){root?.remove();root=null;wb=null;rows=[];result=null;}
 function loadSheet(){const sheet=wb.Sheets[sheetName],ref=sheet['!fullref']||sheet['!ref'];if(!ref)throw Error('工作表为空');const range=xlsx().utils.decode_range(ref);if(range.e.r>2000||range.e.c>49)throw Error('每张工作表最多2000行数据、50列，请拆分后重试');const all=xlsx().utils.sheet_to_json(sheet,{header:1,defval:'',raw:false,blankrows:true});if(!Number.isInteger(headerRow)||headerRow<1||headerRow>all.length)throw Error('表头行不在工作表范围内');headers=(all[headerRow-1]||[]).map(String);rows=all.slice(headerRow).map((cells,i)=>({row:headerRow+i+1,cells}));mapping=E.autoMap(headers);choices={};skipErrors=false;}
 async function readFile(file){if(!file)return;if(!/\.xlsx?$/i.test(file.name))throw Error('请选择 .xlsx 或 .xls 文件');if(file.size>5*1024*1024)throw Error('文件不能超过5MB');busy=true;render();try{const buffer=await file.arrayBuffer();if(!root)return;wb=xlsx().read(buffer,{type:'array',cellFormula:false,cellHTML:false,sheetRows:2002});filename=file.name;sheetName=wb.SheetNames[0];headerRow=1;loadSheet();step=1;}finally{busy=false;if(root)render();}}
 function render(){if(!root)return;const state=getState();const checks=step===2?E.preview(state,rows,mapping):[];root.querySelector('.excel-modal').innerHTML=`<header><div><div class="eyebrow">LEADFLOW / EXCEL</div><h2>${step===3?'导入完成':'从 Excel 导入线索'}</h2></div>${button('关闭','close')}</header><div class="excel-steps">${['选择文件','字段映射','校验与去重','导入结果'].map((v,i)=>`<span class="${step===i?'current':''}">${i+1}. ${v}</span>`).join('')}</div><div class="excel-body">${step===0?upload():step===1?mapView():step===2?previewView(checks):resultView(state)}<div class="excel-error" role="alert"></div></div><footer>${step===1?button('重新选文件','restart')+button('校验并预览','preview','primary'):step===2?button('返回字段映射','mapping')+button('确认导入','import','primary'):step===3?button('完成','close','primary'):''}</footer>`;}
 function upload(){return `<div class="excel-upload"><h3>将线索表格放进工作台</h3><p>支持 .xlsx / .xls，最多5MB、2000行数据、50列。文件只在当前浏览器解析。</p><label class="excel-file-label">${busy?'正在解析…':'选择 Excel 文件'}<input type="file" id="excel-file" accept=".xlsx,.xls" ${busy?'disabled':''}></label></div><div class="actions excel-downloads"><a class="excel-download" href="files/leadflow-template.xlsx" download>下载标准模板</a><a class="excel-download" href="files/leadflow-sample.xlsx" download>下载演示示例（含错误与重复）</a>${button('载入演示示例','sample')}</div><p class="form-note">必填：客户姓名、手机号、来源、意向车型。负责人填写销售姓名或ID，留空进入线上直营主管待分配池。车型库：${catalogRules()}。支持 +86、空格及横线手机号格式归一化。</p><p class="form-note">可用销售：林悦 / u1、周辰 / u2、许宁 / u3、陆远 / u4。模板仅第一张表用于填写，规则说明在第二张表。</p>`;}
 function mapView(){return `<div class="excel-file-info"><b>${esc(filename)}</b><span>${rows.filter(r=>r.cells.some(c=>String(c).trim())).length} 行待校验</span></div><div class="excel-source"><label>工作表<select id="excel-sheet">${wb.SheetNames.map(n=>`<option${selected(n,sheetName)}>${esc(n)}</option>`).join('')}</select></label><label>表头所在行<input type="number" id="excel-header" value="${headerRow}" min="1" max="2001"></label></div><div class="excel-mappings">${E.fields.map(f=>`<label><span>${f.label}${f.required?' <em>*</em>':''}</span><select data-map="${f.key}" aria-label="映射${f.label}"><option value="-1">${f.required?'请选择列':'不导入此字段'}</option>${headers.map((h,i)=>`<option value="${i}"${selected(i,Number(mapping[f.key]))}>${i+1}. ${esc(h||'（空表头）')}</option>`).join('')}</select><small>首行示例：${esc(rows[0]?.cells[Number(mapping[f.key])]??'—')}</small></label>`).join('')}</div><p class="form-note">已自动匹配同义表头。每一列只能映射到一个字段，可手动调整后校验。</p>`;}
 function previewView(checks){const errors=checks.filter(r=>r.errors.length).length,duplicates=checks.filter(r=>!r.errors.length&&r.duplicate).length;return `<div class="excel-summary"><b>${checks.length} 行</b><span class="hot">${errors} 行错误</span><span>${duplicates} 行重复</span><span>${checks.length-errors-duplicates} 行可新增</span></div><label class="check-field"><input id="excel-skip-errors" type="checkbox"${skipErrors?' checked':''}>跳过错误行，继续导入有效数据</label><p class="form-note">重复行必须逐条选择合并或跳过。同一文件的重复手机号也会识别。合并保留原负责人、状态、来源、车型和联系许可，导入字段留存在批次记录，备注追加。</p><div class="excel-table-wrap"><table><thead><tr><th>Excel行</th>${E.fields.map(f=>`<th>${f.label}</th>`).join('')}<th>校验结果 / 处理</th></tr></thead><tbody>${checks.map(r=>`<tr class="${r.errors.length?'excel-invalid':r.duplicate?'excel-duplicate':''}"><td>${r.row}</td>${E.fields.map(f=>`<td>${esc(r.data[f.key]||'—')}</td>`).join('')}<td>${r.errors.length?`<span class="hot">${esc(r.errors.join('；'))}</span>`:r.duplicate?`<b>重复：${esc(r.duplicate.label)}</b><select data-choice="${r.row}" aria-label="第${r.row}行去重选择"><option value="">请选择处理方式</option>${r.duplicate.canMerge?`<option value="merge"${selected(choices[r.row],'merge')}>合并到已有线索</option>`:''}<option value="skip"${selected(choices[r.row],'skip')}>跳过</option></select>${!r.duplicate.canMerge?'<small>请由该线索负责人或主管合并</small>':''}`:'<span class="badge green">可新增</span>'}</td></tr>`).join('')}</tbody></table></div>`;}
 function resultView(state){return `<div class="excel-success-mark">✓</div><h3>批次 #${esc(result.id)} 已保存</h3><div class="excel-summary"><b>成功 ${result.success}</b><b>合并 ${result.merged}</b><b>跳过 ${result.skipped}</b></div><p class="form-note">数据已保存到当前浏览器。负责人为空的新线索已进入主管待分配池；切换沈知行查看看板。重置演示会清除导入及合并内容。</p><div class="excel-table-wrap"><table><thead><tr><th>Excel行</th><th>结果</th><th>线索 / 原因</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.row}</td><td>${r.status}</td><td>${esc(r.lead||r.reason)}</td></tr>`).join('')}</tbody></table></div>`;}
 function error(err){if(root)root.querySelector('.excel-error').textContent=err.message||String(err);else notify(err.message);}
 async function click(e){e.stopPropagation();const action=e.target.closest('[data-excel]')?.dataset.excel;if(!action)return;try{if(action==='close'){close();return;}if(action==='restart'){open();return;}if(action==='sample'){const response=await fetch('files/leadflow-sample.xlsx');if(!response.ok)throw Error('示例文件加载失败');await readFile(new File([await response.arrayBuffer()],'leadflow-sample.xlsx'));return;}if(action==='preview'){const errs=E.mappingErrors(mapping);if(errs.length)throw Error(errs.join('；'));if(!rows.some(r=>r.cells.some(c=>String(c).trim())))throw Error('工作表没有数据行');step=2;render();}if(action==='mapping'){step=1;render();}if(action==='import'){if(step!==2||busy)return;busy=true;try{const imported=E.importRows(getState(),rows,mapping,choices,{skipErrors,filename});commit(imported.state);result=imported.result;step=3;render();}finally{busy=false;}}}catch(err){error(err);}}
 async function change(e){e.stopPropagation();try{const t=e.target;if(t.id==='excel-file'){await readFile(t.files[0]);return;}if(t.id==='excel-sheet'||t.id==='excel-header'){const oldSheet=sheetName,oldHeader=headerRow;try{sheetName=root.querySelector('#excel-sheet').value;headerRow=Number(root.querySelector('#excel-header').value);loadSheet();render();}catch(err){sheetName=oldSheet;headerRow=oldHeader;render();throw err;}}if(t.dataset.map){mapping[t.dataset.map]=Number(t.value);render();}if(t.dataset.choice)choices[t.dataset.choice]=t.value;if(t.id==='excel-skip-errors')skipErrors=t.checked;}catch(err){error(err);}}
 function exportFile(leads){if(getState().user!=='mgr')throw Error('仅主管可导出团队线索');const X=xlsx(),book=X.utils.book_new(),sheet=X.utils.aoa_to_sheet(E.exportRows(leads));sheet['!cols']=E.fields.map(f=>({wch:f.key==='note'?55:20})).concat([{wch:15},{wch:15},{wch:15},{wch:20}]);sheet['!autofilter']={ref:sheet['!ref']};X.utils.book_append_sheet(book,sheet,'当前筛选线索');X.writeFile(book,'LeadFlow-筛选线索-'+new Date(getState().now+8*3600000).toISOString().slice(0,10)+'.xlsx',{bookType:'xlsx'});notify('已导出 '+leads.length+' 条线索（当前团队与来源筛选，存量快照）');}
 return {open,close,exportFile};
}
